                        "Lanes: the card transmits on PCIE_TX0 (AC-coupled here with C5, C6, 0.22 µF) and receives on PCIE_RX0; REFCLK comes from the host. All 85 Ω pairs, length-matched within the pair. PERST# is pulled up (R3) and driven by the host.",
