                    PlannedConnection(from: "D2.K", to: "GND7.GND"),
                    PlannedConnection(from: "U4.11", to: "RL2.1"),
                    PlannedConnection(from: "RL2.2", to: "D3.A"),
                    PlannedConnection(from: "D3.K", to: "GND7.GND"),
                ],
                notes: ["Segment 1 — Power: QR (AO3400) is an ideal diode in the battery return (gate from VBUS through RQ1 / RQ2 ≈ 7.7 V), F1 (5 A) protects against a stalled motor, D1 (SMBJ28A) clamps inductive spikes; U1 makes the 12 V gate-drive rail, U2 5 V, U3 3.3 V logic. ADuM1201 (U5) separates the MCU from the gate-driver signals — power its side 2 from an isolated DC-DC and split the grounds for full galvanic isolation.",
                        "Segment 2 — Compute: ATmega328P at 3.3 V; UART debug on J1. A Jetson / CM4 carrier replaces it on vision robots (HDI, DDR / PCIe / MIPI length matching).",
                        "Segment 3 — Motion: IR2104 (U6) drives the IRF540N half-bridge (Q1 / Q2) with bootstrap DB / CB and 10 Ω gate resistors. RS (10 mΩ) is Kelvin-sensed into U7 (gain 1 + 20k / 1k = 21) → IMOTOR on ADC0 for FOC / stall detection. Bolt the TO-220 FETs to the aluminium chassis; Auto Route stitches thermal vias at SMD FETs.",
                        "Segment 4 — Sensors: MPU-6050 (U8) on I²C with 4.7 kΩ pull-ups, kept ≥ 10 mm from the power stage by Auto Place; the analog front end returns to AGND, joined to GND only at FB1 (ferrite star point). TJA1050 (U9) drives CANH / CANL with RT 120 Ω termination on J2.",
                        "Segment 5 — Comms: nRF24L01+ (U10) on SPI, placed away from the switching stage; use a shield can on a production board.",
                        "Segment 6 — Safety: SW1 is a normally-closed E-stop from +5V to ESTOP with RE pulling it low — pressing it (or a broken wire) pulls the IR2104 SD pin low and kills both gates without the MCU; U5 reports ESTOP to the MCU. D2 (power, green) and D3 (fault, red) show the state.",
                        "Segment 7 — Mechanical: four M3 holes on a 50 mm pattern; Auto Place keeps ceramic capacitors out of their flex zone."],
                board: PlannedBoard(width: 60, height: 60, layers: 4, mountingHoleSpacing: 50),
