                notes: ["Segment 1 — Protection front-end: QR (IRLZ44N) is an ideal diode in the battery return; its gate is biased from the battery through RQ1 / RQ2 (≈ 6.8 V at 13.5 V, 12 V at a 24 V jump start), so a reversed battery leaves it off (ISO 16750-2 reverse voltage). F1 (5 A) protects the harness; D1 (SM8S33A, 6.6 kW) clamps an unsuppressed load dump (ISO 16750-2 test A) and ISO 7637-2 pulses; C1–L1–C2 form the pi filter for CISPR 25. A production ECU replaces QR with an LM74700-Q1 ideal-diode controller and F1 with a TPS1213-Q1 eFuse.",
                        "Segment 2 — Regulation: U1 (LM2940-5.0, 45 V load-dump rated, reverse-battery protected) makes +5V with 0.5 V dropout, so the logic rides through normal cranking (battery ≥ 5.5 V); a severe 4 V cold crank needs a buck-boost pre-regulator (LM5175-Q1 / TPS55165-Q1). U2 (XC6206) makes a quiet +3V3A for the sensor amplifier. U3 (TPS3823-50-Q1) holds the MCU in reset below 4.55 V and resets it if PD3 stops toggling WDI for 1.6 s.",
                        "Segment 3 — MCU: ATmega328P at 5 V with Y1 (8 MHz, AEC-Q200) for timing; U5 (24LC256) on I²C stores DTCs and calibration. ASIL-C/D functions move to a lockstep MCU (AURIX TC3xx, Stellar, RH850) with a safety PMIC.",
                        "Segment 4 — Networks: U6 (MCP2518FD, 20 MHz Y2) is the CAN-FD controller on SPI; U7 (TJA1044GT) drives CANH / CANL with RT (120 Ω, fit only at the bus ends) and D4 / D5 bus ESD diodes; route CANH / CANL as a 120 Ω differential pair (Auto Route matches them). U8 (TJA1021) is the LIN master on the UART: DL + RLIN (1 kΩ) pull the bus to battery, D6 protects it, PD4 drives SLP_N.",
                        "Segment 5 — Actuation: U9 (IR2104) drives the Q1 / Q2 (IRF540N) half-bridge from a 15 V-clamped gate supply (RD / DZ); RS (50 mΩ) senses the motor current into ADC1 through RF / CF for stall and pinch detection. LM / RM model the window-lift motor. Lamp and heater loads use PROFET high-side switches (BTS7008-2EPA) with their IS output read by the MCU.",
                        "Segment 6 — Sensors: the harness inputs SENS_P / SENS_N pass through D7 / D8 (ESD), RIP / RIN (1 kΩ) and CIP / CIN (10 nF) into U10 (INA333, G = 101 with RG 1 kΩ) on the analog rail; RBP / RBN (1 MΩ) bias an open wire to full scale so the MCU detects it. RO / CO filter the output into ADC0.",
                        "Board: 4 layers with a GND plane on layer 1, high-Tg FR-4, AEC-Q100 / Q200 parts rated −40 … 125 °C. Keep the front end at the connector edge, the half-bridge on its own copper, and the sensor amplifier away from it."],
                board: PlannedBoard(width: 75, height: 60, layers: 4, mountingHoleSpacing: 50, material: "fr4-hightg"),
                pours: [PlannedPour(net: "GND", layer: 1, plane: true)],
                netClasses: [PlannedNetClass(net: "VBAT_F", width: 1.0), PlannedNetClass(net: "VBAT", width: 1.0), PlannedNetClass(net: "PHASE", width: 0.5), PlannedNetClass(net: "MOTOR_B", width: 0.5), PlannedNetClass(net: "VBOOT", width: 0.6)],
                noConnect: ["U3.3", "U6.3", "U6.8", "U6.9", "U8.8", "U4.15", "U4.25", "U4.26"],
                ecuType: "bcm"),
            blocks: ["Protection front-end", "Voltage regulation", "Microcontroller", "Vehicle networks", "Actuation", "Sensor conditioning"],
            supply: 13.5,
            category: "Automotive",
