        Template(
            keywords: ["aerospace", "avionics", "satellite", "cubesat", "spacecraft", "on-board computer", "obc", "flight computer", "rad-hard", "radiation hard", "radiation-hard", "rad hard", "triple modular", "tmr", "spacewire", "mil-std-1553", "1553", "arinc", "single event", "latch-up", "latchup", "mram", "ipc-6012ds", "space-class", "space class"],
            plan: DesignPlan(
                title: "Satellite On-Board Computer: 5-Segment Aerospace Reference",
                summary: "A LEO satellite / avionics computer built from the five aerospace design segments: (1) three rad-tolerant ATmegaS128 lanes in triple modular redundancy with a 74HC00 + 74HC10 majority voter, an MR25H40 MRAM per lane and a TPS2553 current limiter per lane that its TPS3823 watchdog power-cycles on latch-up or a hang; (2) a 28 V bus with a 3 A fuse, MPLAD15KP36CA lightning TVS and pi filter into an isolated 28 V → 5 V DC-DC with a separate bus return; (3) an isolated sensor domain (isolated 5 V, INA333 + MCP3201 behind ADuM1201 isolators) and a MAX31855K thermocouple input with cold-junction compensation; (4) a SpaceWire port on UT54LVDS031 / 032 with 100 Ω termination; (5) a UHF telemetry transceiver module with a DC block, 50 Ω low-pass and an edge SMA — on a 6-layer Rogers RO4350B board.",
