                ],
                notes: ["Segment 1 — Compute: lanes A / B / C (U1–U3, ATmegaS128: SEL-immune to 62 MeV·cm²/mg, 30 krad) run the same software. Each drives its command on PB5 (CMD_A / _B / _C, 100 kΩ pull-downs so an unpowered lane reads 0); U10 (74HC00) forms the pairwise NANDs and U11 (74HC10) the final NAND, so VOTED_CMD = AB + BC + AC and one upset lane is outvoted. Each lane keeps state in its own MR25H40 MRAM (U4–U6) on SPI.",
                        "Latch-up protection: each lane is powered through a TPS2553 (U7–U9, ILIM 47 kΩ — set the trip just above the lane's operating current per the datasheet ILIM equation). A latch-up trips it within microseconds; its FAULT pulls the lane watchdog's MR low, and the TPS3823 (U12–U14) holds RESET low for 200 ms, which also opens the switch (EN), so the die is power-cycled. A lane that stops kicking WDI (PB4) for 1.6 s is cycled the same way.",
                        "Segment 2 — Power: V1 is the 28 V bus (MIL-STD-704) with its return on RTN, never on logic ground. F1 (3 A; an SSPC in flight hardware), D1 (MPLAD15KP36CA, DO-160 lightning) and C1–L1–C2 condition it; PS1 is an isolated 28 V → 5 V converter (MHF+2805S / SVR2805S class, 16–50 V in); RBL / CY bleed static between the domains. U15 makes +3V3 for lanes A / C, U24 +3V3_IO for the voter and LVDS, U25 +3V3_B for lane B and its radio (three LDOs keep each cool at 125 °C).",
                        "Segment 3 — Sensors: PS2 makes an isolated ISO_5V / AGND_ISO domain; SENS_P / SENS_N pass D6 / D7 (TVS), RIP / RIN and CIP / CIN into U16 (INA333, G = 101; RBP / RBN 100 kΩ drive an open wire to full scale) whose filtered output feeds U17 (MCP3201). U18 / U19 (ADuM1201) carry the ADC's clock, chip select and data across the barrier to lane A. U20 (MAX31855K) reads a K thermocouple on TC+ / TC− with on-chip cold-junction compensation (use an ungrounded junction).",
                        "Segment 4 — Avionics: U21 / U22 (UT54LVDS031 / 032, 300 krad) are the SpaceWire physical layer to J3 (data and strobe each way, 100 Ω differential, RT1 / RT2 at the receiver; Auto Route length-matches the _P / _N pairs). The data-strobe codec belongs in an FPGA (RTG4) or a GR718 router; lane C only exercises the link here. Military boards add a transformer-coupled dual MIL-STD-1553 terminal, commercial avionics ARINC 429 line drivers.",
                        "Segment 5 — RF: U23 is a UHF (437 MHz) telemetry transceiver module (CC1101 / Si4463 class, SPI on lane B, its own TCXO and matching) whose 50 Ω RF pin runs through the DC block CDC and a 5th-order 50 Ω low-pass (CF1–CF3, LF1 / LF2, fc ≈ 500 MHz) to the SMA J4 at the board edge. A bare 0.5 mm-pitch QFN radio does not escape under the Space preset spacing — hence the module. Fit a machined aluminium shield can over the RF section on a via-fenced ground ring.",
                        "Board: Rogers RO4350B (low loss, low outgassing; a production board uses a hybrid Rogers / polyimide stack), 50 Ω single-ended, GND plane on layer 1, 6 layers for the three TQFP-64 lanes, IPC-6012DS, SnPb solder, staked parts and conformal coating."],
                board: PlannedBoard(width: 120, height: 95, layers: 6, mountingHoleSpacing: 64, material: "rogers-4350b", singleEndedOhms: 50),
                pours: [PlannedPour(net: "GND", layer: 1, plane: true)],
                netClasses: [PlannedNetClass(net: "AGND_ISO", width: 0.5)],
                noConnect: ["U15.4", "U24.4", "U25.4", "U10.11", "U11.6", "U11.8", "U19.2", "U20.8", "J2.6", "U21.10", "U21.11", "U21.13", "U21.14", "U22.9", "U22.10", "U22.11", "U22.13", "U22.14", "U22.15", "U1.1", "U1.2", "U1.3", "U1.5", "U1.6", "U1.7", "U1.8", "U1.16", "U1.17", "U1.19", "U1.23", "U1.24", "U1.25", "U1.26", "U1.27", "U1.28", "U1.32", "U1.33", "U1.34", "U1.35", "U1.36", "U1.37", "U1.38", "U1.39", "U1.40", "U1.41", "U1.42", "U1.43", "U1.44", "U1.45", "U1.46", "U1.47", "U1.48", "U1.49", "U1.50", "U1.51", "U1.54", "U1.55", "U1.56", "U1.57", "U1.58", "U1.59", "U1.60", "U1.61", "U2.1", "U2.2", "U2.3", "U2.4", "U2.6", "U2.7", "U2.8", "U2.9", "U2.16", "U2.17", "U2.18", "U2.19", "U2.23", "U2.24", "U2.29", "U2.30", "U2.31", "U2.32", "U2.33", "U2.34", "U2.35", "U2.36", "U2.37", "U2.38", "U2.39", "U2.40", "U2.41", "U2.42", "U2.43", "U2.44", "U2.45", "U2.46", "U2.47", "U2.48", "U2.49", "U2.50", "U2.51", "U2.54", "U2.55", "U2.56", "U2.57", "U2.58", "U2.59", "U2.60", "U2.61", "U3.1", "U3.2", "U3.3", "U3.4", "U3.9", "U3.16", "U3.17", "U3.18", "U3.19", "U3.23", "U3.24", "U3.25", "U3.26", "U3.27", "U3.28", "U3.29", "U3.30", "U3.31", "U3.32", "U3.33", "U3.34", "U3.35", "U3.36", "U3.37", "U3.38", "U3.39", "U3.40", "U3.41", "U3.42", "U3.43", "U3.44", "U3.45", "U3.46", "U3.47", "U3.48", "U3.49", "U3.50", "U3.51", "U3.54", "U3.55", "U3.56", "U3.57", "U3.58", "U3.59", "U3.60", "U3.61"],
