                notes: ["Segment 1 — Power: V1 is the 28 V DC ship's supply (return RTN, never logic ground). F1 (3 A) and RV1 (S14K35 varistor) take MIL-STD-1399 / MIL-STD-1275 surges; GDT1 / GDT2 divert common-mode lightning and weapon-switching surges to CHASSIS; D1 clamps the residue and C1–L1–C2 filter for MIL-STD-461 CE102. PS1 is an isolated 28 V → 5 V forward / flyback converter; RBL / CY bleed static between the domains. AC supplies (115 / 440 V, 60 / 400 Hz) add a PFC boost stage (UCC28019) ahead of the converter.",
                        "Segment 2 — Corrosion: U2 (ATmegaS128) is in a ceramic hermetic package; the board is Parylene-C coated with a 2 mm copper-free border (Fit Board margin) for the coating to anchor and 0.25 mm minimum spacing against dendritic growth. Use ENIG or SnPb finishes, no bare copper or pure tin.",
                        "Segment 3 — Shock: underfill / corner bonding under U2, PS1 and the bulk capacitors; four plated, via-stitched M3 holes 60 mm apart; 8-layer 2.4 mm polyimide stack for rigidity (MIL-STD-901E Grade A, MIL-STD-167).",
                        "Segment 4 — Data: the UART runs over fibre (U3 transmitter driven by Q1, U4 receiver) so the ship's radar cannot couple into it. The RS-485 node sits on its own isolated ISO_5V / GND_ISO domain (PS2), with U5 / U6 (ADuM1201) carrying TX, RX and direction across the barrier to U7 (MAX485), RT (120 Ω) and D6 / D7 bus TVS. Legacy combat systems add NTDS (MIL-STD-1397) line drivers.",
                        "Segment 5 — RF / sonar: J2 → CDC1 → D2 / D3 (BAP64 antiparallel PIN limiter) protect U8 (LNA MMIC, biased through RBIAS / LCH) from the ship's own radar; CDC2 couples to J3. The hydrophone pair HYD_P / HYD_N passes D4 / D5, RIP / RIN and CIP / CIN into U9 (INA333, G = 101) on AGND, joined to GND only at FB1; U10 makes the quiet +3V3A rail. Shield the sonar front end and keep it away from U2."],
