            keywords: ["iec 60601", "60601", "mopp", "patient isolation", "patient monitor", "defibrillator", "defib", "type cf", "type bf", "driven right leg", "right leg drive", "rld", "medical device", "medical electronics", "ecg monitor", "ecg front end", "biosignal", "biopotential", "iso 13485", "infusion pump", "healthcare"],
            plan: DesignPlan(
                title: "Defibrillator-Proof ECG Monitor: 4-Segment Medical Reference",
                summary: "A type CF, battery-powered ECG monitor built from the four medical design segments: (1) the patient electrodes on their own isolated domain (ISO-DCDC-MED 5 kV converter, ADuM4401 5 kV isolator, 8 mm barrier kept by placement, routing, pours and DRC) with GDT + 10 kΩ + TVS defibrillator protection on every lead; (2) an INA333 lead-I amplifier, a driven-right-leg integrator and an MCP3201 ADC on the patient ground; (3) an MCU with a TPS3823 watchdog, a TP4056 charger with NTC cut-off and a DW01A protector with its two MOSFETs on the Li-ion cell; (4) a BLE module on a 50 Ω feed to an edge U.FL and ESD clamps on every connector pin.",
