                notes: ["Segment 1 — Patient isolation: everything touching the patient (J1 electrodes through U6, U7, U8) lives on the ISO_5V / PGND domain. PS1 (medical isolated DC-DC, 5 kV reinforced, < 10 pF barrier capacitance → leakage < 2 µA) powers it and U5 (ADuM4401, 5 kV, wide body) carries SCK / CS out and the ADC data back. The board's isolation barrier is 8 mm (2 × MOPP): Auto Place keeps the domains 8 mm apart, Auto Route fences them and the GND / PGND pours stop 8 mm short; mill a slot under U5 and PS1 for the full 8 mm creepage across their bodies. No Y-capacitor or bleed resistor crosses the barrier.",
                        "Defibrillator protection: each lead (ECG_RA, ECG_LA, ECG_RL) has a GDT-90V to PGND at the connector and a 10 kΩ pulse-rated series resistor (MELF, 5 kV pulse) ahead of the D1 / D2 clamps and the 1 nF RC filters, so a 5 kV defibrillator discharge is diverted and limited before the amplifier (IEC 60601-2-27).",
                        "Segment 2 — Biosignal: U6 (INA333, G = 101 with RG 1 kΩ) amplifies lead I (LA − RA) around VMID (ISO_5V / 2); RCM1 / RCM2 sense the common mode and U7 integrates it against VMID and drives it back through RDRL (390 kΩ, limits patient current to ≈ 10 µA) into the right-leg electrode, cancelling 50 / 60 Hz hum. U8 (MCP3201) digitises the filtered output on the patient ground.",
                        "Segment 3 — Safety compute & power: U3 (ATmega328P) must kick U4 (TPS3823) every 1.6 s or it is reset. A life-support device uses a lockstep MCU (TMS570) and a windowed watchdog that forces the safe state. The cell (B1) charges through U1 (TP4056, 500 mA, NTC on TEMP stops charging when hot) and is guarded by U2 (DW01A) switching Q1 / Q2 (over-charge, over-discharge, over-current) — two independent cut-offs.",
                        "Segment 4 — Coexistence: U9 (BLE module) feeds J3 (U.FL at the board edge) over a 50 Ω line above the GND plane; DUSB and the GDTs clamp every connector pin (IEC 61000-4-2 ±15 kV air). Solder a nickel-silver shield can over U3 and U9 against electrosurgical noise."],
                board: PlannedBoard(width: 100, height: 70, layers: 4, singleEndedOhms: 50, isolationGap: 8),
                pours: [PlannedPour(net: "GND", layer: 1, plane: false), PlannedPour(net: "PGND", layer: 2, plane: false)],
                netClasses: [PlannedNetClass(net: "BAT+", width: 0.8), PlannedNetClass(net: "VBUS", width: 0.8)],
                noConnect: ["J2.3", "J2.4", "U1.6", "U1.7", "U2.4", "U10.4", "U4.3", "U3.6", "U3.9", "U3.10", "U3.11", "U3.12", "U3.13", "U3.14", "U3.15", "U3.17", "U3.23", "U3.24", "U3.25", "U3.26", "U3.27", "U3.28", "PS1.3", "PS1.4", "PS1.5", "PS1.6", "U5.12"],
