            plan: DesignPlan(
                title: "Countertop Payment Terminal + Receipt Printer: 4-Segment POS Reference",
                summary: "A countertop POS controller built from the four retail design segments: (1) a payment SECURE-MCU under an active tamper mesh laid by the autorouter on Inner 1 / Inner 2 (no via can be drilled through the secure area), case-open switches on its tamper inputs, keys kept alive on a coin cell and an NCN8025 EMV contact front end; (2) an 80 mm thermal print head with 1000 µF at VH, a DRV8833 paper-feed stepper driver on its thermal pad and an AO3400 auto-cutter driver with flyback; (3) a USB2514B hub (host, secure MCU and scanner ports), an opto-isolated 24 V cash-drawer kick and 100 Ω LVDS display lanes; (4) USBLC6 / TPD4E ESD arrays on every exterior pin and an acrylic conformal coat.",
