                notes: ["Segment 1 — Payment security: U3 (secure MCU) drives TAMPER_MESH_A out of MESH_A_DRV and reads it back on MESH_A_SNS (likewise mesh B). Auto Route lays mesh A as horizontal stripes on Inner 1 and mesh B as vertical stripes on Inner 2 over U3 plus 2 mm, 0.15 mm lines at 0.5 mm pitch; every other track and every via keeps out of that area, and DRC flags anything that breaches it. Drilling, probing or cutting into the secure area opens or shorts a mesh line and U3 zeroizes its keys. J5 brings the case-open switches (normally closed to GND, 1 MΩ pull-ups to the coin cell) to TAMPER1 / TAMPER2. B1 (CR2032) keeps VBAT, the key RAM and the tamper detectors alive with mains off.",
                        "Card entry: U4 (NCN8025) generates the card VCC from +5 V through L2, level-shifts I/O, RST and CLK to the ISO 7816 contacts on J4 and reports card presence; the TPD4E1U06 and D5 clamp the card-slot pins. Fit the contactless (NFC) antenna and the magstripe head on their own modules; the magstripe AFE inputs of U3 are left open here.",
                        "Segment 2 — Printer: J6 is the 80 mm head (24 V VH). C20 (1000 µF low-ESR) and C21 sit at the head so a full dot line (several amps for ~300 µs) does not sag +24 V. U7 (DRV8833) drives the paper-feed stepper on J7 from +5 V with 0.2 Ω sense resistors (≈ 1 A limit); its PowerPAD lands on the GND pour — stitch 6–9 thermal vias under it to the bottom pour. Q1 switches the auto-cutter solenoid (J8) with D8 across the coil. U6 (ATmega328P) shifts dot data over SPI, fires STB1 / STB2, steps the motor and reads the head thermistor; it talks to U3 over UART.",
                        "Segment 3 — HMI & peripherals: U5 (USB2514B, 24 MHz Y1) fans the host port J1 out to U3 (port 1) and the scanner port J2 (ports 3 and 4 are free for a customer display or a second reader); the scanner VBUS has its own polyfuse. U8 (PC817) isolates the drawer kick: U6 lights the LED, the transistor turns Q2 on and the 24 V solenoid on J9 fires with D9 catching the turn-off spike. J10 → J11 pass the LVDS display lanes (clock + data) as 100 Ω pairs.",
                        "Segment 4 — ESD & environment: USBLC6-2SC6 on every USB port, TPD4E1U06 on the card slot and LVDS, SMBJ28A on the DC input; acrylic (AR) conformal coat against spilled drinks and cleaning sprays — mask the connectors and the card slot."],
                board: PlannedBoard(width: 120, height: 90, layers: 4, coating: "acrylic"),
                pours: [PlannedPour(net: "GND", layer: 0, plane: false), PlannedPour(net: "GND", layer: -1, plane: false)],
                netClasses: [PlannedNetClass(net: "+24V", width: 0.8), PlannedNetClass(net: "DC_IN", width: 0.8), PlannedNetClass(net: "SW", width: 0.8), PlannedNetClass(net: "+5V", width: 0.6), PlannedNetClass(net: "CUTTER_SOL", width: 0.5), PlannedNetClass(net: "DRAWER_KICK", width: 0.5)],
                noConnect: ["U2.4", "U3.7", "U3.8", "U3.18", "U3.19", "U3.20", "U3.21", "U3.28", "U3.29", "U3.30", "U3.31", "U4.5", "U4.7", "U4.8", "U4.18", "U4.19", "U4.21", "U4.23", "U4.24", "D3.5", "U5.6", "U5.7", "U5.8", "U5.9", "U5.12", "U5.16", "U5.18", "U5.20", "U5.25", "U5.28", "D13.5", "U6.9", "U6.10", "U6.18", "U6.21", "U6.26", "U6.27", "U6.28"],
