            plan: DesignPlan(
                title: "Washing Machine Controller: 4-Segment Home Appliance Reference",
                summary: "A 230 VAC washing-machine main board built from the four appliance segments: (1) mains entry with a slow-blow fuse, S10K275 varistor, X2 capacitor and common-mode choke, a bridge and bulk capacitor feeding an LNK306 non-isolated buck (15 V) and 5 V / 3.3 V rails; (2) a drain-pump triac (BT136) fired by a MOC3021 with an RC snubber, H11AA1 zero-cross detection and a three-phase IPM with an emitter shunt for the inverter drum motor; (3) AT42QT1070 capacitive touch keys with series resistors, a filtered NTC water-temperature divider and an A3144 drum-speed hall sensor; (4) an ESP32-WROOM-32E at the board edge, clear of mains copper. Every mains net keeps its IPC-2221 spacing in placement, routing and pours.",
