                notes: ["Segment 1 — Mains entry: J1 brings L / N to F1 (T 2 A slow-blow, in the line), RV1 (S10K275) and CX1 (100 nF X2, 15 mm pitch) across L–N, then the common-mode choke (L1 / L2, both windings of one 10 mH part) and the D1–D4 bridge into C1 (47 µF / 400 V). U1 (LNK306) switches the bus into a high-side buck: D5 freewheels, L3 / C2 hold +15 V for the IPM; U2 (LM2596-5.0) and U3 (AP2112K) make 5 V and 3.3 V. The controller is NOT isolated from the mains — the whole board is live: enclose it and treat the touch panel and connectors as mains-referenced (reinforced insulation in the user interface, IEC 60335-1 §8 / §29).",
                        "Voltage spacing: with mains on the board, Auto Place, Auto Route and the pours fence every high-voltage net (L, N, the bus, the switch node) by its IPC-2221 spacing — 0.8 mm for 325 V peak under the acrylic coat — while the 3.3 V logic keeps the normal 6-mil rules; DRC checks every pair. IEC 60335 / 60664 asks more creepage (2.5 mm functional L–N, 6–8 mm reinforced): add milled slots between L and N at the fuse, MOV and triac.",
                        "Segment 2 — Actuation: U4 (MOC3021) fires Q1 (BT136-600E, leads formed to 5.08 mm) for the drain pump on J2; R7 + C5 (39 Ω + 10 nF) snub the inductive load. U5 (H11AA1) pulses ZERO_CROSS at each mains zero for phase timing. U6 (IPM, 600 V) drives the drum motor on J3 from the bus with bootstrap capacitors on each phase and one 50 mΩ emitter shunt (RS1) feeding CIN (hardware over-current trip) and the ESP32 ADC (sensorless FOC).",
                        "Segment 3 — HMI & sensing: U7 (AT42QT1070) reads three touch keys on the front-panel connector J4 through 1 kΩ series resistors (hatch a ground guard round the pads on the panel board); RT1 (10 kΩ NTC) and R18 form the water-temperature divider, C18 filters it at the ADC; U8 (A3144) on the drum pulley gives speed and imbalance feedback.",
                        "Segment 4 — IoT: U9 (ESP32-WROOM-32E) is both the controller and the Wi-Fi / BLE link; it sits at the top edge with its PCB antenna pointing out, ≥ 6 mm from mains copper. Keep copper off both layers under the antenna."],
                board: PlannedBoard(width: 130, height: 90, layers: 4, coating: "acrylic"),
                pours: [PlannedPour(net: "GND", layer: 0, plane: false), PlannedPour(net: "GND", layer: -1, plane: false)],
                noConnect: ["U1.3", "U3.4", "U9.4", "U9.5", "U9.17", "U9.18", "U9.19", "U9.20", "U9.21", "U9.22", "U9.24", "U9.25", "U9.28", "U9.29", "U9.30", "U9.31", "U9.32", "U9.34", "U9.35", "U9.37", "U4.3", "U4.5", "U5.3", "U5.6", "U6.11", "U6.12", "U6.13", "U6.14", "U6.18", "U6.20", "U6.23", "U6.26", "U7.5", "U7.6", "U7.7", "U7.8", "U7.12"],
