                notes: ["Segment 1 — Power & decoupling: V1 (5 V) feeds U3 (AP2112K-3.3, 600 mA) with 10 µF in and out. The MCU's 14 VDD pins share C6–C12 (100 nF each, one per pin pair) and C13 (4.7 µF); VDDA has C14 (1 µF); VCAP1 / VCAP2 take C3 / C4 (2.2 µF) for the internal core regulator. The SDRAM's seven VDD / VDDQ pins take C20–C23 (100 nF) and C24 (10 µF) right at the package. The +3V3 plane (layer 5) and GND plane (layer 2) carry the supply to every pin through short vias.",
                        "Segment 2 — Clock, command & address: FMC bank 1 (SDCKE0 = PH2, SDNE0 = PH3, SDNWE = PH5, SDNRAS = PF11, SDNCAS = PG15, SDCLK = PG8). R2 (22 Ω) sits next to PG8 to damp the clock edge. A0–A12 and BA0–BA1 run point-to-point (SDR SDRAM has no VTT termination).",
                        "Segment 3 — Data integrity: the 16 data lines are named SD_DQ0…SD_DQ15, so Auto Route lays them as one length-matched bus (within 0.5 mm) — at 100–133 MHz SDCLK that keeps setup / hold margin on every bit. DQML / DQMH (PE0 / PE1) mask the bytes.",
                        "Segment 4 — Configuration: firmware sets the FMC SDRAM timings for the MT48LC16M16A2-6A (CAS latency 3 at 133 MHz: tRCD 18 ns, tRP 18 ns, tRC 60 ns, 8192 refresh / 64 ms), then sends clock enable, precharge-all, two auto-refresh and the mode register. BOOT0 is pulled low (R1); J1 is the SWD header (3.3 V, SWCLK, GND, SWDIO, NRST, SWO); Y1 (8 MHz) is the HSE for the PLL.",
                        "Segment 5 — Layout: 6 layers (signal / GND / signal / signal / 3.3 V / signal) with the SDRAM beside the MCU's FMC pins; every bus line runs over a solid plane. The HDI / Fine-Pitch preset (from the Memory industry profile) suits the 0.5 mm LQFP-176. For DDR3L / DDR4 memory-down use MT41K256M16HA-125 or MT40A512M16LY-062E with VTT, VREF, ZQ and RESET_n per the Memory segments."],
                board: PlannedBoard(width: 80, height: 60, layers: 6),
                pours: [PlannedPour(net: "GND", layer: 1, plane: true), PlannedPour(net: "+3V3", layer: 4, plane: true)],
